import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createServer } from "vite";

/**
 * The shared wind field: fidelity to the model, and the clock's behaviour.
 *
 * Two separate claims are checked here and they need different references.
 *
 * The first is that the port reproduces the model it came from. That is
 * measured against `source-cinematic-wind.json`, generated by running the
 * source implementation itself over a fixed sample grid, with the port using
 * the source's own gradient hash. Bit-identical is achievable there and is what
 * is required: both are double precision doing the same arithmetic.
 *
 * The second is that the shipped field — which samples a periodic gradient
 * lattice instead of hashing, so the CPU and the GPU can agree at all — is a
 * well-formed field with the same structure. That cannot be compared against
 * the source fixture, because changing the gradient source changes the field by
 * design. It is checked for the properties the field must have, and the
 * CPU-versus-GPU agreement is measured in the browser by
 * `check-renderer-harness.mjs wind`.
 */
const SCRIPT_DIRECTORY = dirname(fileURLToPath(import.meta.url));
const REPOSITORY_ROOT = resolve(SCRIPT_DIRECTORY, "..");

const server = await createServer({
  configFile: false,
  server: { middlewareMode: true },
  optimizeDeps: { noDiscovery: true, include: [] },
});

const failures = [];
const check = async (name, run) => {
  try {
    await run();
  } catch (error) {
    failures.push(new Error(`${name}: ${error.message}`));
  }
};

try {
  const math = await server.ssrLoadModule("/src/world/weather/WorldWindMath.ts");
  const lattice = await server.ssrLoadModule("/src/world/weather/WorldWindLattice.ts");
  const { WorldWindField } = await server.ssrLoadModule("/src/world/weather/WorldWindField.ts");
  const fixture = JSON.parse(readFileSync(
    resolve(REPOSITORY_ROOT, "docs/plans/fixtures/source-cinematic-wind.json"), "utf8",
  ));

  // --- Fidelity to the source model ----------------------------------------

  await check("the gradient noise reproduces the source exactly", () => {
    let worst = 0;
    for (const sample of fixture.noise) {
      const value = math.windGradientNoise2d(
        sample.x, sample.y, lattice.windSourceHashGradient,
      );
      worst = Math.max(worst, Math.abs(value - sample.value));
    }
    assert.equal(worst, 0,
      `Same arithmetic in the same precision must give the same number; worst ${worst}.`);
  });

  await check("the field reproduces the source over the sample grid", () => {
    let worst = 0;
    let worstAt = null;
    for (const sample of fixture.samples) {
      const got = math.sampleWorldWind({
        x: sample.x, z: sample.z, time: sample.time,
        directionDegrees: sample.directionDegrees,
        gradient: lattice.windSourceHashGradient,
      });
      for (const [key, expected, actual] of [
        ["directionX", sample.dx, got.directionX],
        ["directionZ", sample.dz, got.directionZ],
        ["strength", sample.strength, got.strength],
        ["gust", sample.gust, got.gust],
        ["turbulence", sample.turbulence, got.turbulence],
        ["flutter", sample.flutter, got.flutter],
      ]) {
        const delta = Math.abs(expected - actual);
        if (delta > worst) {
          worst = delta;
          worstAt = { key, sample };
        }
      }
    }
    assert.equal(worst, 0,
      `The port must reproduce the source model exactly; worst ${worst} at `
      + JSON.stringify(worstAt));
  });

  // --- The shared lattice ---------------------------------------------------

  await check("the lattice is periodic and wraps negative cells", () => {
    const period = lattice.WIND_LATTICE_PERIOD;
    for (const [x, y] of [[0, 0], [5, 9], [-1, -1], [-300, 412]]) {
      const base = lattice.windLatticeGradient(x, y);
      const wrapped = lattice.windLatticeGradient(x + period, y - period * 2);
      assert.deepEqual([...base], [...wrapped],
        `The lattice must repeat exactly at its period, including negatively.`);
    }
    assert.equal(lattice.wrapLatticeIndex(-1), period - 1);
    assert.equal(lattice.wrapLatticeIndex(period), 0);
  });

  await check("the lattice holds unit gradients", () => {
    const gradients = lattice.getWindGradientLattice();
    assert.equal(gradients.length, lattice.WIND_LATTICE_PERIOD ** 2 * 2);
    let worst = 0;
    for (let index = 0; index < gradients.length; index += 2) {
      const length = Math.hypot(gradients[index], gradients[index + 1]);
      worst = Math.max(worst, Math.abs(length - 1));
    }
    // Float32 storage, so unit length holds to single precision.
    assert.ok(worst < 1e-6, `Gradients must be unit vectors; worst error ${worst}.`);
  });

  await check("the shipped field stays in range everywhere", () => {
    for (let index = 0; index < 4000; index++) {
      // Deliberately unpleasant coordinates: far negative, far positive, and
      // long elapsed values a session could actually reach.
      const x = ((index * 79) % 4096) - 2048.5;
      const z = ((index * 131) % 4096) - 2048.25;
      const time = (index % 7) * 1800;
      const sample = math.sampleWorldWind({ x, z, time, directionDegrees: (index * 13) % 360 });
      for (const [key, value] of Object.entries(sample)) {
        assert.ok(Number.isFinite(value), `${key} must stay finite at (${x}, ${z}, t=${time}).`);
      }
      assert.ok(sample.gust >= 0 && sample.gust <= 1, "The gust must stay in [0, 1].");
      assert.ok(sample.strength >= 0.06 - 1e-9 && sample.strength <= 1.25 + 1e-9,
        `The envelope must stay within its configured bounds; got ${sample.strength}.`);
      assert.ok(Math.abs(Math.hypot(sample.directionX, sample.directionZ) - 1) < 1e-9,
        "The direction must stay a unit vector.");
    }
  });

  await check("the direction convention is (cos, sin) of the angle", () => {
    // Fixed once here, and used unchanged by the node functions. Transposing x
    // and z in one shader and not another is what makes a gust front travel the
    // wrong way in a single LOD.
    for (const degrees of [0, 90, 180, 270]) {
      const sample = math.sampleWorldWind({
        x: 0, z: 0, time: 0, directionDegrees: degrees,
        config: { ...math.WORLD_WIND_DEFAULTS,
          direction: { ...math.WORLD_WIND_DEFAULTS.direction, variationDegrees: 0 } },
      });
      const radians = degrees * math.DEGREES_TO_RADIANS;
      assert.ok(Math.abs(sample.directionX - Math.cos(radians)) < 1e-9);
      assert.ok(Math.abs(sample.directionZ - Math.sin(radians)) < 1e-9);
    }
  });

  // --- The clock ------------------------------------------------------------

  await check("a bad delta advances nothing", () => {
    const field = new WorldWindField();
    field.update(1);
    const before = field.getPhaseSeconds();
    for (const delta of [Number.NaN, Number.POSITIVE_INFINITY, -1, 0]) {
      field.update(delta);
      assert.equal(field.getPhaseSeconds(), before,
        `A delta of ${delta} must not move the phase.`);
    }
    assert.ok(Number.isFinite(field.getPhaseSeconds()));
  });

  await check("a long stall does not teleport the field", () => {
    const field = new WorldWindField();
    field.update(30);
    assert.ok(field.getPhaseSeconds() <= 0.1 + 1e-9,
      "One enormous frame must advance by the clamp, not by thirty seconds.");
  });

  await check("changing speed does not jump the phase", () => {
    const field = new WorldWindField();
    for (let frame = 0; frame < 100; frame++) {
      field.update(1 / 60);
    }
    const beforeChange = field.getPhaseSeconds();
    field.setSimulationSpeed(4);
    assert.equal(field.getPhaseSeconds(), beforeChange,
      "Changing the speed must not retroactively rewrite where the wind has been.");
    field.update(1 / 60);
    const step = field.getPhaseSeconds() - beforeChange;
    assert.ok(Math.abs(step - 4 / 60) < 1e-9,
      "The new speed applies from now on, at four times the rate.");
  });

  await check("speed zero freezes the phase without resetting it", () => {
    const field = new WorldWindField();
    for (let frame = 0; frame < 50; frame++) {
      field.update(1 / 60);
    }
    const frozen = field.getPhaseSeconds();
    assert.ok(frozen > 0);
    field.setSimulationSpeed(0);
    for (let frame = 0; frame < 50; frame++) {
      field.update(1 / 60);
    }
    assert.equal(field.getPhaseSeconds(), frozen,
      "Freezing must stop the dynamic phase, not rewind it: the rest bend stays.");
    field.setSimulationSpeed(1);
    field.update(1 / 60);
    assert.ok(field.getPhaseSeconds() > frozen, "Unfreezing resumes from where it stopped.");
  });

  await check("intensity A to B and back recovers A numerically", () => {
    const field = new WorldWindField();
    field.update(1 / 60);
    field.setIntensity(1);
    const before = field.sample(12.5, -7.25);
    field.setIntensity(2.5);
    field.sample(12.5, -7.25);
    field.setIntensity(1);
    const after = field.sample(12.5, -7.25);
    assert.deepEqual({ ...after }, { ...before },
      "Gain is applied to the field, never compounded into it.");
  });

  await check("invalid state changes are refused, not applied", () => {
    const field = new WorldWindField();
    field.setSimulationSpeed(2);
    field.setSimulationSpeed(Number.NaN);
    assert.equal(field.getSimulationSpeed(), 2);
    field.setSimulationSpeed(-1);
    assert.equal(field.getSimulationSpeed(), 2, "A negative speed would run the wind backwards.");
    field.setDirectionDegrees(35);
    field.setDirectionDegrees(Number.NaN);
    assert.equal(field.getDirectionDegrees(), 35);
    field.setNoiseScale(0);
    assert.ok(field.getNoiseScale() > 0, "A zero noise scale would collapse the field to one cell.");
  });

  await check("the field is stationary in space when frozen", () => {
    const field = new WorldWindField();
    field.setSimulationSpeed(0);
    field.update(1 / 60);
    const first = field.sample(40, -18);
    field.update(1 / 60);
    const second = field.sample(40, -18);
    assert.deepEqual({ ...second }, { ...first });
  });
} finally {
  await server.close();
}

if (failures.length > 0) {
  for (const failure of failures) {
    console.error(`[world-wind] ${failure.message}`);
  }
  throw new Error(`[world-wind] ${failures.length} checks failed.`);
}

console.log(
  "[world-wind] The port reproduces the source model exactly over 960 samples, the "
  + "shared lattice is periodic and unit-normed, the field stays bounded over the "
  + "world and long sessions, and the integrated phase survives speed changes, "
  + "freezing and bad deltas.",
);
